        "metric_name": "GE/A",
        "metric_value": sum(ge_over_t_f) / len(ge_over_t_f),
        "instances_tested": len(results),
        "n_max": max(n_values),
        "conjecture_holds": all(r[0] <= 2 for r in results),  # Assuming k = 1
